class Solution:
    def interactionCosts(self, n: int, edges: List[List[int]], group: List[int]) -> int:
        adj = [[] for _ in range(n)]
        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)

        # Iterative DFS from root 0: parent array and a parent-before-child order
        parent = [-1] * n
        order = []
        stack = [0]
        while stack:
            node = stack.pop()
            order.append(node)
            for nb in adj[node]:
                if nb != parent[node]:
                    parent[nb] = node
                    stack.append(nb)

        ans = 0
        for g in set(group):
            total = group.count(g)
            if total < 2:
                continue
            cnt = [1 if group[i] == g else 0 for i in range(n)]
            # children are processed before their parent in reversed order
            for node in reversed(order):
                p = parent[node]
                if p >= 0:
                    # same-group pairs whose path uses edge (node, p)
                    ans += cnt[node] * (total - cnt[node])
                    cnt[p] += cnt[node]
        return ans
